SQL_DTL_CTN:
SELECT * FROM (
SELECT DIVISION_CODE, DIVISION_CODE || ' ' || DIVISION_NAME AS DIVISION_NAME, CODE, NAME, SALES_SITE_CODE, SALES_SITE_NAME FROM ( SELECT X0.*, CODE AS SALES_SITE_CODE, NAME AS SALES_SITE_NAME FROM ( SELECT * FROM (SELECT DIVISION_CODE, (SELECT MIN(V.DIVISION_NAME) FROM SCM_MST_DIVISION V WHERE V.DIVISION_ID = X.DIVISION_CODE) AS DIVISION_NAME, CODE, NAME FROM ( SELECT DISTINCT A.DIVISION_ID AS DIVISION_CODE, A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME FROM SCM_MST_SITE A WHERE A.SITE_TYPE = 'SALES' AND A.VALID_YN = 'Y' AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D' AND USE_YN = 'Y') ) X ORDER BY DIVISION_CODE, CODE) X9 WHERE X9.DIVISION_CODE NOT IN (SELECT V9.DIVISION_ID FROM SCM_MST_DIVISION V9 WHERE V9.ATTRIBUTE3 = 'EE') ) X0 ) X3
) ORDER BY UPPER(CODE)

SELECT * FROM (
SELECT DIVISION_CODE, DIVISION_CODE || ' ' || DIVISION_NAME AS DIVISION_NAME, CODE, NAME, END_CUSTOMER_CODE, END_CUSTOMER_NAME FROM ( SELECT X0.*, CODE AS END_CUSTOMER_CODE, NAME AS END_CUSTOMER_NAME FROM ( SELECT * FROM (SELECT DIVISION_CODE, (SELECT MIN(V.DIVISION_NAME) FROM SCM_MST_DIVISION V WHERE V.DIVISION_ID = X.DIVISION_CODE) AS DIVISION_NAME, CODE, NVL((SELECT MIN(L.SEGMENT3) FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = 'END_CUSTOMER' AND L.VALID_YN = 'Y' AND L.SEGMENT1 = X.DIVISION_CODE AND L.SEGMENT2 = X.CODE), X.CODE) AS NAME FROM ( SELECT DISTINCT A.DIVISION_ID AS DIVISION_CODE, A.PROJECT_CODE AS CODE FROM SCM_MST_SITE_ITEM A WHERE A.DIVISION_ID = '40' AND A.VALID_YN = 'Y' AND A.PROJECT_CODE IS NOT NULL AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D' AND USE_YN = 'Y') UNION ALL SELECT DISTINCT A.DIVISION_ID, A.END_CUSTOMER FROM SCM_MST_SITE A WHERE A.DIVISION_ID <> '40' AND A.END_CUSTOMER IS NOT NULL AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D' AND USE_YN = 'Y') ) X ORDER BY DIVISION_CODE, CODE) X9 WHERE X9.DIVISION_CODE NOT IN (SELECT V9.DIVISION_ID FROM SCM_MST_DIVISION V9 WHERE V9.ATTRIBUTE3 = 'EE') ) X0 ) X3
) ORDER BY UPPER(CODE)

SELECT * FROM (
SELECT DIVISION_CODE, DIVISION_CODE || ' ' || DIVISION_NAME AS DIVISION_NAME, CODE, NAME, END_CUSTOMER_CODE, END_CUSTOMER_NAME FROM ( SELECT X0.*, CODE AS END_CUSTOMER_CODE, NAME AS END_CUSTOMER_NAME FROM ( SELECT * FROM (SELECT * FROM (SELECT DIVISION_CODE, (SELECT MIN(V.DIVISION_NAME) FROM SCM_MST_DIVISION V WHERE V.DIVISION_ID = X.DIVISION_CODE) AS DIVISION_NAME, CODE, NVL((SELECT MIN(L.SEGMENT3) FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = 'END_CUSTOMER' AND L.VALID_YN = 'Y' AND L.SEGMENT1 = X.DIVISION_CODE AND L.SEGMENT2 = X.CODE), X.CODE) AS NAME FROM ( SELECT DISTINCT A.DIVISION_ID AS DIVISION_CODE, A.PROJECT_CODE AS CODE FROM SCM_MST_SITE_ITEM A WHERE A.DIVISION_ID = '40' AND A.VALID_YN = 'Y' AND A.PROJECT_CODE IS NOT NULL AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D' AND USE_YN = 'Y') UNION ALL SELECT DISTINCT A.DIVISION_ID, A.END_CUSTOMER FROM SCM_MST_SITE A WHERE A.DIVISION_ID <> '40' AND A.END_CUSTOMER IS NOT NULL AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D' AND USE_YN = 'Y') ) X ORDER BY DIVISION_CODE, CODE) X) X9 WHERE X9.DIVISION_CODE NOT IN (SELECT V9.DIVISION_ID FROM SCM_MST_DIVISION V9 WHERE V9.ATTRIBUTE3 = 'EE') ) X0 ) X3
) ORDER BY UPPER(CODE)

SELECT * FROM (
SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, A.END_CUSTOMER, B.PROJECT_CODE FROM SCM_MGR.SCM_MST_SITE A LEFT JOIN SCM_MGR.SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID WHERE A.SITE_TYPE = 'SALES' AND A.VALID_YN = 'Y' AND ( @divisionId IS NULL OR @divisionId = 'ALL' OR INSTR(',' || @divisionId || ',', ',' || A.DIVISION_ID || ',') > 0 ) AND ( @endCustomer IS NULL OR @endCustomer = 'ALL' OR INSTR(',' || @endCustomer || ',', ',' || CASE WHEN @divisionId = '40' THEN B.PROJECT_CODE ELSE A.END_CUSTOMER END || ',') > 0 ) AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D') UNION ALL SELECT NULL AS DIVISION_ID, C.COMPANY_ID AS CODE, C.COMPANY_ID AS NAME, NULL AS END_CUSTOMER, NULL AS PROJECT_CODE FROM SCM_MGR.SCM_MST_COMPANY_SN C
) ORDER BY UPPER(DIVISION_ID), UPPER(CODE)

SELECT * FROM (
SELECT DISTINCT L.SEGMENT2 AS CODE , L.SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = 'END_CUSTOMER' AND L.VALID_YN = 'Y' AND L.SEGMENT1 = @divisionId
) ORDER BY UPPER(CODE)

SELECT * FROM (
SELECT X1.*, SALES_SITE_CODE AS CODE, SALES_SITE_NAME AS NAME FROM ( SELECT X0.*, END_CUSTOMER AS END_CUSTOMER_CODE, SALES_SITE AS SALES_SITE_CODE FROM ( SELECT DISTINCT END_CUSTOMER, END_CUSTOMER_NAME, SALES_SITE, SALES_SITE_NAME FROM ( SELECT * FROM (SELECT V.DIVISION_ID, V.DIVISION_ID || ' ' || V.DIVISION_NAME AS DIVISION_NAME, X.DEPT_ID, (SELECT CASE @sesLangCd WHEN 'EN' THEN D9.DEPT_NAME_EN WHEN 'CN' THEN D9.DEPT_NAME_CN ELSE D9.DEPT_NAME_KO END FROM SCM_MST_SSO_DEPT_INFO D9 WHERE D9.DEPT_ID = X.DEPT_ID) AS DEPT_NAME, X.END_CUSTOMER, NVL((SELECT MIN(L9.SEGMENT3) FROM SCM_ADM_LOOKUP_MASTER_DETAIL L9 WHERE L9.LOOKUP_TYPE = 'END_CUSTOMER' AND L9.VALID_YN = 'Y' AND L9.SEGMENT1 = X.DIVISION_ID AND L9.SEGMENT2 = X.END_CUSTOMER), X.END_CUSTOMER) AS END_CUSTOMER_NAME, X.SALES_SITE, X.SALES_SITE_NAME, X.SRC_TYPE, X.SORT_ORDER FROM SCM_MST_DIVISION V JOIN ( SELECT DISTINCT A.DIVISION_ID, (SELECT MAX(SI9.DEPT_ID) FROM SCM_MST_SITE_ITEM SI9 WHERE SI9.DIVISION_ID = A.DIVISION_ID AND SI9.SCM_SITE_ID = A.SCM_SITE_ID) AS DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID AS SALES_SITE, NVL(NULLIF(TRIM(A.SITE_DESCRIPTION), '-'), A.SCM_SITE_ID) AS SALES_SITE_NAME, 'SITE' AS SRC_TYPE, 2 AS SORT_ORDER FROM SCM_MST_SITE A WHERE A.SITE_TYPE = 'SALES' AND A.DIVISION_ID <> '40' AND A.VALID_YN = 'Y' UNION ALL SELECT DISTINCT A.DIVISION_ID, C.DEPT_ID, B.PROJECT_CODE, A.SCM_SITE_ID, NVL(NULLIF(TRIM(A.SITE_DESCRIPTION), '-'), A.SCM_SITE_ID), 'SITE', 2 FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT JOIN SCM_MST_SSO_DEPT_INFO C ON B.DEPT_ID = C.DEPT_ID WHERE A.SITE_TYPE = 'SALES' AND A.DIVISION_ID = '40' AND A.VALID_YN = 'Y' UNION ALL SELECT DISTINCT L.SEGMENT3, NULL, NULL, L.SEGMENT1, L.SEGMENT2, 'AS', 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = 'AS_SITE_PLANT' AND L.VALID_YN = 'Y' ) X ON V.DIVISION_ID = X.DIVISION_ID WHERE V.ATTRIBUTE3 <> 'EE' AND V.VALID_YN = 'Y' AND V.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = 'D' AND USE_YN = 'Y')) WHERE (EXISTS (SELECT 1 FROM SCM_ADM_USER_GR_MPG_M G WHERE G.USER_ID = @sesUserId AND G.USER_GR_ID IN ( SELECT L9.SEGMENT1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L9 WHERE L9.LOOKUP_TYPE = 'GET_ADMIN_GROUP' AND L9.VALID_YN = 'Y' AND L9.SEGMENT2 = 'ALL' ) AND G.USE_YN = 'Y') OR DEPT_ID IN (SELECT L.SEGMENT3 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = 'PM_TEAM_MAPPING' AND L.VALID_YN = 'Y' AND L.SEGMENT1 IN (SELECT U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U WHERE U.USER_ID = @sesUserId) UNION SELECT U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U WHERE U.USER_ID = @sesUserId)) ) WHERE END_CUSTOMER IS NOT NULL ORDER BY END_CUSTOMER, SALES_SITE ) X0 ) X1
) ORDER BY UPPER(CODE)
